// ===============================
// ITEM ATUAL
// ===============================
const item = $input.item.json;
// ===============================
// PARSE DOS DADOS META
// ===============================
let dadosMeta;
try {
  dadosMeta =
    typeof item.dados_meta === 'string'
      ? JSON.parse(item.dados_meta)
      : item.dados_meta;
} catch (e) {
  throw new Error('dados_meta não é um JSON válido');
}
// ===============================
// SEGURANÇAS
// ===============================
if (!dadosMeta || !Array.isArray(dadosMeta.parametros)) {
  throw new Error('dados_meta.parametros não é um array');
}
if (!dadosMeta.template_whatsapp) {
  throw new Error('template_whatsapp não informado');
}
// ===============================
// MONTA BODY PARAMETERS
// ===============================
const bodyParameters = dadosMeta.parametros.map(p => {
  if (p.source === 'nome') {
    return {
      type: 'text',
        text: (() => { const n = String(item.name || '').trim().split(/\s+/)[0] || ''; return n.charAt(0).toUpperCase() + n.slice(1).toLowerCase(); })()
    };
  }
  if (p.source === 'legenda') {
    return {
      type: 'text',
      text: String(p.value || '')
        .replace(/\n\n/g, ' | ')
        .replace(/\n/g, ' ')
        .replace(/\t/g, ' ')
        .replace(/ {5,}/g, '    ')
    };
  }
  if (p.source === 'link') {
  return {
    type: 'text',
    text: String(p.value || '')
  };
}
  // fallback de segurança
  return {
    type: 'text',
    text: ''
  };
});
// ===============================
// COMPONENTS
// ===============================
const components = [];
// HEADER (mídia)
if (
  dadosMeta.media_type &&
  dadosMeta.media_type !== 'none' &&
  dadosMeta.media_url
) {
  components.push({
    type: 'header',
    parameters: [
      {
        type: dadosMeta.media_type,
        [dadosMeta.media_type]: {
          link: dadosMeta.media_url
        }
      }
    ]
  });
}
// BODY
components.push({
  type: 'body',
  parameters: bodyParameters
});
// ===============================
// RETORNO FINAL (META API)
// ===============================
return {
  json: {
    messaging_product: 'whatsapp',
    to: String(item.phone_normalized),
    type: 'template',
    template: {
      name: dadosMeta.template_whatsapp,
      language: {
        code: dadosMeta.language || 'pt_BR'
      },
      components
    }
  }
};

// ===============================
// DADOS DE ENTRADA
// ===============================
// Mensagens diárias (AGORA É ARRAY)
const mensagens = $('Merge').all();

// Linha do template vinda do Supabase
const template = $input.item.json;

// ===============================
// SEGURANÇAS
// ===============================
if (!template.variables || !Array.isArray(template.variables)) {
  throw new Error('Template sem array de variables no Supabase');
}

// ===============================
// PROCESSAR CADA CONTATO
// ===============================
const resultados = mensagens.map(item => {

  const mensagem = item.json;

  // ===============================
  // VALIDA PHONE NUMBER
  // ===============================
  if (!mensagem.dados_meta?.phone_number_id_meta) {
    throw new Error('phone_number_id_meta não encontrado no Switch1');
  }

  const phoneId = mensagem.dados_meta.phone_number_id_meta;

  // ===============================
  // LINK DO WEBHOOK
  // ===============================
  const linkOrigem = $('Webhook').first().json.body.post.origem || '';

  // ===============================
  // QUEBRA DA LEGENDA
  // ===============================
  const blocosLegenda = (mensagem.legenda_whatsapp || '')
    .split(/\n\s*\n/)
    .map(t => t.trim())
    .filter(Boolean);

  // ===============================
  // VARIÁVEIS DO TEMPLATE
  // ===============================
  const variables = template.variables;
  const totalVars = variables.length;

  // ===============================
  // MONTA PARAMETROS
  // ===============================
  const parametros = [];
  let legendaCursor = 0;

  for (let i = 0; i < totalVars; i++) {

    const varName = variables[i];

    if (varName === 'nome_usuario') {

      parametros.push({
        type: 'text',
        source: 'nome'
      });

    } else if (varName === 'resumo_completo') {

      // Pega o texto inteiro da célula sem dividir em blocos
      parametros.push({
        type: 'text',
        source: 'legenda',
        value: mensagem.legenda_whatsapp || ''
      });

    } else if (varName === 'link') {

      parametros.push({
        type: 'text',
        source: 'link',
        value: linkOrigem
      });

    } else {

      parametros.push({
        type: 'text',
        source: 'legenda',
        value: blocosLegenda[legendaCursor] || ''
      });

      legendaCursor++;
    }
  }

  // ===============================
  // DEFINE MÍDIA (SE EXISTIR)
  // ===============================
  let media_type = 'none';
  let media_url = null;

  if (template.media_type && template.media_type !== 'none') {
    media_type = template.media_type;
    media_url = template.media_url || mensagem.imagem1 || null;
  }

  // ===============================
  // RETORNO PARA ESTE CONTATO
  // ===============================
  return {
    json: {
      ...mensagem,
      phone_number_id_meta: phoneId,
      dados_meta: {
        template_whatsapp: template.meta_template_name,
        meta_template_id: template.meta_template_id,
        language: template.language || 'pt_BR',
        media_type,
        media_url,
        parametros
      }
    }
  };

});

return resultados;

// ============================================================
// Monta o body do template de onboarding (boas-vindas do Journal)
// Roda apenas para quem tem precisa_onboarding = true
//
// O template 'onboarding_clientes' tem header de IMAGEM. A Meta exige
// o componente header com a midia em TODO envio — a imagem enviada na
// criacao do template e apenas amostra. Por isso a URL abaixo.
// Precisa ser https, publica e acessivel pela Meta (sem login).
// ============================================================
const item = $input.item.json;

const TEMPLATE   = 'onboarding_clientes';
const LANG       = 'pt_BR';
const IMAGEM_URL = 'https://s3.us-east-1.amazonaws.com/cdn.miabuilder.com/BMS%2FJournal%2FOnBoardingJournal.jpg';   // <-- preencher antes de ativar

// mesmo tratamento de nome usado no fluxo de post: primeiro nome, capitalizado
const primeiroNome = (() => {
  const n = String(item.name || '').trim().split(/\s+/)[0] || '';
  return n.charAt(0).toUpperCase() + n.slice(1).toLowerCase();
})();

// texto equivalente ao template aprovado na Meta, so para registrar no historico
const texto = `📢 Olá, *${primeiroNome}*, tudo bem?\n\nVocê está entre os primeiros a receber acesso ao nosso Agente de IA Tributária, criado pela *BMS Consultoria Tributária* para manter nossos parceiros sempre à frente.\n\nToda semana, enviaremos para você as *principais notícias e novidades do mundo tributário*, filtradas nas fontes mais relevantes, para que não perca nada que impacta empresas e negócios.\n\nEspero que goste dessa novidade. 🚀`;

return {
  json: {
    nome: primeiroNome,
    texto,
    body: {
      messaging_product: 'whatsapp',
      to: String(item.phone_normalized),
      type: 'template',
      template: {
        name: TEMPLATE,
        language: { code: LANG },
        components: [
          // header de imagem — obrigatorio porque o template declara midia
          { type: 'header', parameters: [{ type: 'image', image: { link: IMAGEM_URL } }] },
          // body — variavel unica {{1}} = primeiro nome
          { type: 'body',   parameters: [{ type: 'text', text: primeiroNome }] }
          // o botao "Parar notificacoes" nao tem variavel, entao nao entra no payload
        ]
      }
    }
  }
};

// ============================================================
// Depois do ramo de onboarding, os nos Supabase/Wait trocaram o item
// da esteira. Aqui devolvemos o item original do lead (lead + dados_meta)
// para que "Monta o body de requisicao pra Meta" receba o que espera.
// ============================================================
return { json: $('Wait1').first().json };

